def max_sum(tri, n):
    """Write a function to find the maximum sum in the given right triangle of numbers."""
    if n <= 0 or not tri:
        return 0
    n = min(n, len(tri))
    dp = list(tri[n - 1][:n])
    for r in range(n - 2, -1, -1):
        row = tri[r]
        dp = [row[c] + max(dp[c], dp[c + 1]) for c in range(r + 1)]
    return dp[0] if dp else 0
